<?php
require_once __DIR__.'/../_bootstrap.php';
require_method('POST');$user=require_permission('certificates.issue');require_csrf();$in=json_input();$id=(int)($in['id']??0);if($id<1)api_error('Certificate id is required.',422,['id'=>'Required.']);$q=db()->prepare('SELECT c.*,i.id inspection_id,i.reference FROM certificates c JOIN inspections i ON i.id=c.inspection_id WHERE c.id=? LIMIT 1');$q->execute([$id]);$c=$q->fetch();if(!$c)api_error('Certificate not found.',404);$reason=normalize_text_input((string)($in['reason']??'Incomplete issuance requires evidence repair.'),true);$db=db();$db->beginTransaction();try{$now=now_sql();$q=$db->prepare('UPDATE certificates SET status=?,revoked_at=?,revocation_reason=?,updated_at=? WHERE id=?');$q->execute(['revoked',$now,$reason,$now,$id]);$q=$db->prepare('UPDATE inspections SET status=?,approved_at=NULL,updated_at=? WHERE id=?');$q->execute(['correction',$now,(int)$c['inspection_id']]);$q=$db->prepare('INSERT INTO inspection_comments (inspection_id,user_id,comment_type,comment_text,created_at) VALUES (?,?,?,?,?)');$q->execute([(int)$c['inspection_id'],(int)$user['id'],'correction',$reason,$now]);audit_log((int)$user['id'],'certificates.repair_opened','certificate',$id,['inspection_id'=>(int)$c['inspection_id'],'reason'=>$reason]);$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();api_error('Unable to open certificate repair.',500);}respond(['message'=>'Certificate marked invalid and source inspection reopened for correction.','inspection_id'=>(int)$c['inspection_id'],'certificate_id'=>$id]);
